import { useEffect } from 'react';

import { VERIFIER_WS_URL } from '@/lib/services/verifier.constants';

const WS_NORMAL_CLOSURE = 1000;
const WS_POLICY_VIOLATION = 1008;

/**
 * useVerifierWebSocket - Listens for the authentication result over WebSocket.
 *
 * @param state - Session state generated by the verifier (from useVerifierQR)
 */
export const useVerifierWebSocket = (state: string) => {
  useEffect(() => {
    if (!state) return;

    const wsUrl = `${VERIFIER_WS_URL}?state=${encodeURIComponent(state)}`;
    const socket = new WebSocket(wsUrl);

    socket.onmessage = (event) => {
      try {
        const message = JSON.parse(event.data as string) as {
          type: string;
          redirectUrl?: string;
        };

        switch (message.type) {
          case 'session':
            break;

          case 'authenticated':
            if (message.redirectUrl) {
              // Validate that the redirect URL belongs to the same origin. Prevents open redirect if the verifier WebSocket is compromised.
              try {
                const redirectOrigin = new URL(message.redirectUrl).origin;
                if (redirectOrigin !== globalThis.location.origin) {
                  // eslint-disable-next-line no-console -- security signal: open-redirect attempt blocked
                  console.error(
                    'WebSocket redirect blocked: cross-origin redirect attempt',
                    redirectOrigin,
                  );
                  socket.close(WS_POLICY_VIOLATION);
                  break;
                }
              } catch {
                // eslint-disable-next-line no-console -- security signal: invalid redirect URL
                console.error('WebSocket redirect blocked: invalid URL', message.redirectUrl);
                socket.close(WS_POLICY_VIOLATION);
                break;
              }
              globalThis.location.href = message.redirectUrl;
            }
            socket.close(WS_NORMAL_CLOSURE);
            break;

          case 'error':
            socket.close();
            break;
        }
      } catch {
        // Ignore unparseable messages
      }
    };

    socket.onerror = () => { };

    return () => {
      socket.close(WS_NORMAL_CLOSURE);
    };
  }, [state]);
};
